def find_odd_collatz_numbers(n):
    """
    Given a positive integer n, generate the Collatz sequence starting from n until it reaches 1,
    and return a sorted list of all odd numbers encountered in the sequence (including the starting number if odd).
    """
    if n <= 0:
        raise ValueError("Input must be a positive integer.")
    odd_numbers = []
    while n != 1:
        if n % 2 == 1:
            odd_numbers.append(n)
            n = 3 * n + 1
        else:
            n = n // 2
    odd_numbers.append(1)
    return sorted(set(odd_numbers))
```

