def max_strength(groups):
    """
    Given a list of student groups where each group is represented as a list of student strengths,
    this function returns the maximum strength among all groups.
    Strength of a group is defined as the product of strengths of students in the group.

    :param groups: List[List[int]] - List of groups with student strengths
    :return: int - maximum strength among all groups
    """
    def product(lst):
        result = 1
        for num in lst:
            result *= num
        return result

    if not groups:
        return 0
    return max(product(group) for group in groups)

