def color_pairs(n, colors, queries):
    # Initialize adjacency pairs count
    count = 0
    for i in range(n - 1):
        if colors[i] == colors[i + 1]:
            count += 1

    res = []
    for index, new_color in queries:
        idx = index
        old_color = colors[idx]

        if old_color == new_color:
            # No color change, so count stays the same
            res.append(count)
            continue

        # Check left neighbor
        if idx - 1 >= 0:
            if colors[idx - 1] == old_color:
                count -= 1
            if colors[idx - 1] == new_color:
                count += 1

        # Check right neighbor
        if idx + 1 < n:
            if colors[idx + 1] == old_color:
                count -= 1
            if colors[idx + 1] == new_color:
                count += 1

        colors[idx] = new_color
