def longest_semi_repetitive_substring_length(s: str) -> int:
    # A "semi-repetitive" substring has at most one pair of consecutive repeating characters.
    # We'll use a sliding window approach to find the longest such substring.
    n = len(s)
    if n == 0:
        return 0

    left = 0
    count_repeats = 0  # Count how many consecutive repeats in current window
    max_len = 1

    for right in range(1, n):
        if s[right] == s[right-1]:
            count_repeats += 1

        while count_repeats > 1:
            # Need to move left pointer forward to remove one consecutive repeat
            if s[left] == s[left+1]:
                count_repeats -= 1
            left += 1

        max_len = max(max_len, right - left + 1)
    return max_len

