def ways_to_express_n_as_sum_of_unique_powers(n):
    # We assume "unique powers" means sum of powers of 2 (e.g. 1, 2, 4, 8, 16, ...)
    # Otherwise, problem might be ambiguous. Here, we consider powers of 2.
    # We want to count the ways to express n as sum of unique powers of 2.
    # This is equivalent to count subsets of powers of 2 that sum to n
    # because powers of 2 are always unique and distinct.

    # Find all powers of 2 <= n
    powers = []
    p = 1
    while p <= n:
        powers.append(p)
        p <<= 1

    from functools import lru_cache

    @lru_cache(None)
    def dfs(i, total):
        if total == n:
            return 1
        if i == len(powers) or total > n:
            return 0
        # two choices: pick powers[i] or not
        return dfs(i+1, total) + dfs(i+1, total + powers[i])

    return dfs(0, 0)
