def max_sum_almost_unique_slices(A, k, m):
    """
    Returns the maximum sum of subarrays of length k such that:
    - The subarray has at least m distinct numbers
    - At most one number appears more than once (all others appear exactly once)

    If no such subarray exists, returns 0.
    """
    n = len(A)
    if k > n:
        return 0

    counts = {}
    duplicates = 0
    distinct = 0
    current_sum = 0
    max_sum = float('-inf')

    for i in range(n):
        val = A[i]
        counts[val] = counts.get(val, 0) + 1
        current_sum += val
        if counts[val] == 1:
            distinct += 1
        if counts[val] == 2:
            duplicates += 1

        if i >= k:
            left_val = A[i - k]
            counts[left_val] -= 1
            current_sum -= left_val
            if counts[left_val] == 1:
                duplicates -= 1
            if counts[left_val] == 0:
                distinct -= 1
                del counts[left_val]

        if i >= k - 1:
            if duplicates <= 1 and distinct >= m:
                if current_sum > max_sum:
                    max_sum = current_sum

    return max_sum if max_sum != float('-inf') else 0
```

